@router.delete('/api/profile/badges/{badge_id}/asset')
def remove_custom_badge_asset(
    badge_id: int,
    user: User = Depends(get_current_user)
):
    badge = CustomBadge.get_or_none((CustomBadge.id == badge_id) & (CustomBadge.created_by == user.id))
    if not badge:
        raise HTTPException(status_code=404, detail="Badge not found")

    if badge.icon_path and os.path.exists(badge.icon_path):
        os.unlink(badge.icon_path)
        badge.icon_path = None
        badge.save()

    return {"status": "badge icon removed"}
